			FILE_WRITE_ATTRIBUTES_LE | FILE_SYNCHRONIZE_LE));

	fp->is_posix_ctxt = posix_ctxt;

	/* fp should be searchable through ksmbd_inode.m_fp_list
	 * after daccess, saccess, attrib_only, and stream are
	 * initialized.
